import{_ as r,l as i,o as e,c as s,v as t,p as d,x as o,d as p,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"let 多态与值限制","description":"","frontmatter":{"title":"let 多态与值限制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/let-polymorphism.md","filePath":"cs/let-polymorphism.md","lastUpdated":1789023840000}'),c={name:"cs/let-polymorphism.md"};function m(f,a,_,u,E,A){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="let-多态与值限制" tabindex="-1">let 多态与值限制 <a class="header-anchor" href="#let-多态与值限制" aria-label="Permalink to &quot;let 多态与值限制&quot;">​</a></h1><div class="epigraph"><p>只有 let 绑定的、形态像值的表达式才被推广。否则可变单元会把同一个类型变量实例化成互不相干的类型。</p><footer>—— 据 Tofte, Operational Semantics and Polymorphic Type Inference, 1988；Wright, Simple Imperative Polymorphism, 1995；Milner, 1978 整理</footer></div><p>上一课<a href="/cs/hindley-milner-w">算法 W</a>在纯 λ+let 上于 <code>let</code> 处 \\(\\mathrm{Gen}\\)。缺口是<strong>引用与副作用</strong>：<code>let r = ref (fn x =&gt; x) in (r := ...; !r)</code> 若把 \\(r\\) 推成 \\(\\forall\\alpha.\\,\\mathrm{ref}(\\alpha\\to\\alpha)\\)，读写会毁掉健全性。值限制：只对语法值（λ、常量、某些构造）推广。本课钉这条工程规则，不重写 W 的合一。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先看反例直觉：空列表 <code>[]</code> 是值，可给 \\(\\forall\\alpha.\\,\\mathrm{list}\\,\\alpha\\)；<code>ref []</code> 不是值，类型钉成某未知 \\(\\alpha\\) 的 \\(\\mathrm{ref}(\\mathrm{list}\\,\\alpha)\\)，不能一会儿当 <code>int list</code> 一会儿当 <code>bool list</code> 去写。</p><p>Wright 把限制说成「可推广的是值」；SML 与 OCaml 各有放宽（子表达式、膨胀）。Haskell 纯默认无此坑，<code>IORef</code> 仍要小心。</p><h3 id="值限制不是「禁止多态」" tabindex="-1">值限制不是「禁止多态」 <a class="header-anchor" href="#值限制不是「禁止多态」" aria-label="Permalink to &quot;值限制不是「禁止多态」&quot;">​</a></h3><p><code>let id = fn x =&gt; x</code> 仍是 \\(\\forall\\alpha.\\,\\alpha\\to\\alpha\\)。限制打击的是<strong>计算出来的、可能写入的单元</strong>，不是 λ。</p><p><span class="marginnote">Wright 1995（Lisp and Symbolic Computation）。Tofte 的论文与 SML 定义是历史来源。Pierce TAPL 讨论 imperative polymorphism。本课不把区域推断写进来，生命周期在后课。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>W 的 \\(\\mathrm{Gen}(\\Gamma,\\tau)\\) 量化 \\(\\tau\\) 中不在 \\(\\Gamma\\) 出现的变量。若 \\(\\tau=\\mathrm{ref}\\,\\alpha\\) 且 \\(\\alpha\\) 不在 \\(\\Gamma\\)，推广在逻辑上「合法」却与更新语义冲突：\\(\\alpha\\) 会在运行时被钉死两次。缺口是<strong>类型方案与可变存储的交互</strong>，不是子类型。</p>',11)),(e(),d(h,null,{default:o(()=>[n(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LET%5B%22let%20x%20%3D%20e%22%5D%20--%3E%20VAL%7B%22e%20%E6%98%AF%E8%AF%AD%E6%B3%95%E5%80%BC%3F%22%7D%0A%20%20VAL%20--%3E%7C%E6%98%AF%7C%20GEN%5B%22%E6%8E%A8%E5%B9%BF%22%5D%0A%20%20VAL%20--%3E%7C%E5%90%A6%7C%20MONO%5B%22%E4%BF%9D%E6%8C%81%E5%8D%95%E6%80%81%20%2F%20%E5%BC%B1%E6%96%B9%E6%A1%88%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/scope-symtab">作用域</a>：值限制是类型规则，不是名字解析。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>放宽：若能证明表达式无副作用（纯）或类型不含 ref，可再推广。编译器分析须保守。错误信息：「不能推广」常表现为后续使用处类型冲突，要把原因指回 <code>ref</code>。</p><p>不要用 <code>let</code> 包一层无意义的 <code>id</code> 来绕过限制却引入副作用——那是人为打破健全性的尝试，语言应仍拒绝或钉单态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 ML 模块的弱类型变量全文。后课默认：HM + 值限制才与可变存储共存。下一课子类型：另一条「类型之间的宽化」，与量化正交。</p><p>也不把 Rust 的借用当值限制的特例；所有权后课另起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>let 多态在 <code>let</code> 处推广；值限制限制谁配推广。</li><li><code>ref</code> 与更新使任意 \\(\\mathrm{Gen}\\) 不健全。</li><li>纯 λ 无此问题；命令式 ML 必须收。</li><li>出处：Wright, 1995；Tofte；Milner, 1978。</li></ul>',9))])}const x=r(c,[["render",m]]);export{b as __pageData,x as default};
